; ---- text-stream control codes (bytes < 0x20), from the dispatch table at 00:0EF0 ----
; every code not listed here jumps to the same handler as $00 (end of string).
DEF CONST_TXT_END EQU $00 ; end of string (returns to the caller, or to the parent string when nested); handler 00:0F9D
DEF CONST_TXT_CALL EQU $01 ; far sub-string: inline dw addr, db bank; then continues after it; handler 00:0F83
DEF CONST_TXT_SET_Y EQU $02 ; FFBC := imm8 (PROBABLE: vertical position, compared with 144); handler 00:0FAC
DEF CONST_TXT_SET_X EQU $03 ; FFBD := imm8 (PROBABLE: horizontal position, 16-bit FFBD/FFBE); handler 00:0FB3
DEF CONST_TXT_TAB EQU $09 ; x += 0x30 (16-bit add on FFBD/FFBE); handler 00:1018
DEF CONST_TXT_NEWLINE EQU $0D ; x := left margin (FFC1/FFC2), y += line height (FFC6); handler 00:0F68
DEF CONST_TXT_SET_X16 EQU $1C ; FFBD/FFBE := imm16; handler 00:0FEA
DEF CONST_TXT_SET_Y8 EQU $1D ; FFBC := imm8; handler 00:0FF4
DEF CONST_TXT_ADD_X16 EQU $1E ; FFBD/FFBE += imm16; handler 00:0FFB
DEF CONST_TXT_ADD_Y8 EQU $1F ; FFBC += imm8; handler 00:100D
